'use client';
import Link from 'next/link';
import {FormEvent,useMemo,useState} from 'react';
import {ArrowLeft,CheckCircle2,MapPin,ShieldCheck,Truck,Zap} from 'lucide-react';
import {useCart} from '../CartContext';
import {products} from '../products';

const amount=(price:string)=>Number(price.replace(/\D/g,''));
const money=(n:number)=>new Intl.NumberFormat('hu-HU').format(n)+' Ft';

type FormData={name:string;email:string;phone:string;zip:string;city:string;address:string;company:string;tax:string;billingDifferent:boolean;billingZip:string;billingCity:string;billingAddress:string;installation:boolean;note:string;terms:boolean};
const initial:FormData={name:'',email:'',phone:'',zip:'',city:'',address:'',company:'',tax:'',billingDifferent:false,billingZip:'',billingCity:'',billingAddress:'',installation:false,note:'',terms:false};

export default function CheckoutPage(){
 const {items,clear}=useCart(); const [form,setForm]=useState<FormData>(initial); const [sent,setSent]=useState(false); const [orderId,setOrderId]=useState('');
 const lines=useMemo(()=>items.map(x=>({line:x,p:products.find(p=>p.slug===x.slug)!})).filter(x=>x.p),[items]);
 const total=lines.reduce((s,x)=>s+amount(x.p.price)*x.line.qty,0);
 const set=<K extends keyof FormData>(key:K,value:FormData[K])=>setForm(v=>({...v,[key]:value}));
 function submit(e:FormEvent){e.preventDefault(); if(!lines.length)return; const id='TO-'+new Date().toISOString().slice(2,10).replaceAll('-','')+'-'+String(Date.now()).slice(-4); setOrderId(id); setSent(true); clear(); window.scrollTo({top:0,behavior:'smooth'});}
 if(sent)return <main className="checkoutPage"><header className="productTop"><Link href="/" className="backLink"><ArrowLeft/> Főoldal</Link><Link className="productBrand" href="/"><span><Zap/></span><b>Töltés<em>Otthon</em></b></Link></header><section className="wrap successBox"><CheckCircle2/><span className="kicker">RENDELÉS RÖGZÍTVE</span><h1>Köszönjük a rendelést!</h1><p>A rendelési azonosítód: <b>{orderId}</b></p><p className="successNote">A pénztár jelenlegi verziója a teljes rendelési folyamatot és az adatok ellenőrzését teszteli. Automatikus e-mail küldést és szerveroldali rendelésmentést a következő körben kapcsolunk hozzá.</p><Link className="btn" href="/">Vissza a főoldalra →</Link></section></main>;
 if(!lines.length)return <main className="checkoutPage"><header className="productTop"><Link href="/kosar" className="backLink"><ArrowLeft/> Vissza a kosárhoz</Link><Link className="productBrand" href="/"><span><Zap/></span><b>Töltés<em>Otthon</em></b></Link></header><section className="wrap emptyCheckout"><h1>A kosarad üres</h1><p>A pénztár használatához előbb válassz egy töltőt.</p><Link className="btn" href="/#termekek">Töltők megtekintése →</Link></section></main>;
 return <main className="checkoutPage"><header className="productTop"><Link href="/kosar" className="backLink"><ArrowLeft/> Vissza a kosárhoz</Link><Link className="productBrand" href="/"><span><Zap/></span><b>Töltés<em>Otthon</em></b></Link></header><section className="wrap checkoutWrap"><div className="checkoutTitle"><span className="kicker">PÉNZTÁR</span><h1>Rendelési adatok</h1><p>Egy utolsó lépés, és összeáll a rendelésed.</p></div><form className="checkoutGrid" onSubmit={submit}><div className="checkoutForms"><section className="formCard"><div className="formHeading"><span>1</span><div><h2>Kapcsolattartási adatok</h2><p>Ezeken az elérhetőségeken tudunk egyeztetni veled.</p></div></div><div className="fieldGrid"><label className="full">Név *<input required autoComplete="name" value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Teljes név"/></label><label>E-mail *<input required type="email" autoComplete="email" value={form.email} onChange={e=>set('email',e.target.value)} placeholder="nev@email.hu"/></label><label>Telefonszám *<input required type="tel" autoComplete="tel" value={form.phone} onChange={e=>set('phone',e.target.value)} placeholder="+36 30 123 4567"/></label></div></section><section className="formCard"><div className="formHeading"><span>2</span><div><h2>Szállítási cím</h2><p>Ide kéred a kiválasztott töltőt.</p></div></div><div className="fieldGrid addressGrid"><label>Irányítószám *<input required inputMode="numeric" value={form.zip} onChange={e=>set('zip',e.target.value)} placeholder="4025"/></label><label>Település *<input required value={form.city} onChange={e=>set('city',e.target.value)} placeholder="Debrecen"/></label><label className="full">Utca, házszám *<input required autoComplete="street-address" value={form.address} onChange={e=>set('address',e.target.value)} placeholder="Példa utca 12."/></label></div></section><section className="formCard"><div className="formHeading"><span>3</span><div><h2>Számlázás</h2><p>Magánszemély vagy cég adatai is megadhatók.</p></div></div><div className="fieldGrid"><label>Cégnév <input value={form.company} onChange={e=>set('company',e.target.value)} placeholder="Opcionális"/></label><label>Adószám <input value={form.tax} onChange={e=>set('tax',e.target.value)} placeholder="Opcionális"/></label></div><label className="checkRow"><input type="checkbox" checked={form.billingDifferent} onChange={e=>set('billingDifferent',e.target.checked)}/><span>Más számlázási címet adok meg</span></label>{form.billingDifferent&&<div className="fieldGrid addressGrid extraFields"><label>Irányítószám *<input required value={form.billingZip} onChange={e=>set('billingZip',e.target.value)}/></label><label>Település *<input required value={form.billingCity} onChange={e=>set('billingCity',e.target.value)}/></label><label className="full">Utca, házszám *<input required value={form.billingAddress} onChange={e=>set('billingAddress',e.target.value)}/></label></div>}</section><section className="formCard installCard"><label className="installChoice"><input type="checkbox" checked={form.installation} onChange={e=>set('installation',e.target.checked)}/><span className="installIcon"><MapPin/></span><span><b>Telepítést is kérek</b><small>Szakemberünk felveszi veled a kapcsolatot a helyszín és a hálózat egyeztetéséhez. A telepítés díja külön ajánlat alapján kerül meghatározásra.</small></span></label></section><section className="formCard"><label className="noteLabel">Megjegyzés a rendeléshez<textarea rows={4} value={form.note} onChange={e=>set('note',e.target.value)} placeholder="Pl. kaputelefon, telepítéssel kapcsolatos kérdés…"/></label></section></div><aside className="orderSummary"><h2>Rendelésed</h2><div className="summaryLines">{lines.map(({line,p})=><div className="summaryLine" key={p.slug}><span className="summaryIcon"><Zap/></span><div><b>{p.name}</b><small>{String(p.power).replace('.',',')} kW · {line.qty} db</small></div><strong>{money(amount(p.price)*line.qty)}</strong></div>)}</div><div className="summaryRow"><span>Termékek</span><b>{money(total)}</b></div><div className="summaryRow"><span>Szállítás</span><b>Egyeztetés szerint</b></div>{form.installation&&<div className="summaryRow"><span>Telepítés</span><b>Külön ajánlat</b></div>}<div className="summaryTotal"><span>Termékek végösszege</span><strong>{money(total)}</strong><small>bruttó összeg</small></div><label className="termsRow"><input required type="checkbox" checked={form.terms} onChange={e=>set('terms',e.target.checked)}/><span>Elolvastam és elfogadom a rendeléshez szükséges feltételeket. *</span></label><button className="btn orderBtn" type="submit">Megrendelés elküldése →</button><div className="safeNote"><ShieldCheck/><span>Az adatok ellenőrzése után a rendelés véglegesítéséről külön visszaigazolás szükséges.</span></div><div className="deliveryNote"><Truck/><span>A szállítás részleteit a rendelés visszaigazolásakor pontosítjuk.</span></div></aside></form></section></main>}
